#!/usr/bin/env python3
"""Build compact V4.3 model and result schemas."""
from __future__ import annotations
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
FACTS=["support_type","room_location","product_footprint_and_front","surface_position","support_edges_and_corners","load_path","room_relations","operating_approach","associated_user_position","props_activity"]
TRIGGERS=["support_role","room_use_zone","device_surface_position","props_use_relation","operating_access","user_position","device_support_axes","furniture_room_axes","product_scale","support_load_path","support_shape","shared_perspective","support_contact","shadows_reflections"]
CHECKS=["support_role","room_use_zone","device_surface_position","props_use_relation","operating_access","user_position","device_support_axes","furniture_room_axes","product_scale","support_anatomy","shared_perspective","support_contact","shadows_reflections"]
ISSUES=["inappropriate_support","occupied_workstation","misplaced_support_furniture","incoherent_use_zone","unmotivated_device_position","incoherent_prop_arrangement","blocked_operating_path","excessive_reach","no_feasible_user_position","chair_displacement","device_support_axis_conflict","furniture_layout_conflict","implausible_scale","missing_required_support","malformed_support_furniture","conflicting_perspective","unsupported_product","floating","sinking_or_intersection","inconsistent_shadow","inconsistent_reflection"]

def obj(props): return {"type":"object","additionalProperties":False,"required":list(props),"properties":props}
text={"type":"string","minLength":1}; string={"type":"string"}
region=obj({"image":{"type":"string","enum":["generated_scene","original_twin"]},"label":text,"box":{"type":"array","minItems":4,"maxItems":4,"items":{"type":"number","minimum":0,"maximum":1}}})
fact=obj({"visibility":{"type":"string","enum":["observed","partial","unobservable"]},"observation":text,"region":{"anyOf":[{"$ref":"#/$defs/region"},{"type":"null"}]},"visibility_limit":string})
trigger=obj({"answer":{"type":"string","enum":["yes","no","unknown"]},"visibility":{"type":"string","enum":["observed","partial","unobservable"]},"evidence":text,"fact_refs":{"type":"array","minItems":1,"maxItems":10,"uniqueItems":True,"items":{"type":"string","enum":FACTS}},"candidate_id":{"type":"string","pattern":"^[a-z][a-z0-9_]{0,47}$"},"visibility_limit":string})
missing=obj({"exposed_required_region":{"$ref":"#/$defs/region"},"required_support_reason":text,"visible_break_evidence":text,"alternate_load_paths":text,"hidden_limits":text})
candidate=obj({"id":{"type":"string","pattern":"^[a-z][a-z0-9_]{0,47}$"},"physical_relation":text,"hypothesis":text,"trigger_ids":{"type":"array","minItems":1,"maxItems":14,"uniqueItems":True,"items":{"type":"string","enum":TRIGGERS}},"owner_check":{"type":"string","enum":CHECKS},"issue_code":{"type":"string","enum":ISSUES},"disposition":{"type":"string","enum":["retained","rejected"]},"evidence":text,"benign_alternative":text,"alternative_status":{"type":"string","enum":["excluded_by_visible_evidence","remains_substantial","not_assessable"]},"severity":{"type":["integer","null"],"minimum":1,"maximum":4},"confidence":{"type":"string","enum":["low","medium","high"]},"warning_level":{"type":"string","enum":["none","advisory","review"]},"consequence":string,"region":{"anyOf":[{"$ref":"#/$defs/region"},{"type":"null"}]},"missing_support_test":{"anyOf":[{"$ref":"#/$defs/missing_support_test"},{"type":"null"}]}})
assessment=obj({"inventory":{"anyOf":[obj({"scene_extent":{"type":"string","enum":["tight","medium","wide","indeterminate"]},"support_and_room_landmarks_visible":{"type":"boolean"},**{n:{"$ref":"#/$defs/fact"} for n in FACTS}}),{"type":"null"}]},"triggers":{"anyOf":[obj({n:{"$ref":"#/$defs/trigger"} for n in TRIGGERS}),{"type":"null"}]},"defect_candidates":{"type":"array","minItems":0,"maxItems":14,"items":{"$ref":"#/$defs/candidate"}},"stage_status":{"type":"string","enum":["assessed","unable"]},"unable_reason":{"type":["string","null"],"enum":[None,"unreadable_image","target_not_identifiable","product_type_conflict","fundamentally_unjudgeable_product_support"]},"general_artifact_warnings":{"type":"array","maxItems":8,"items":obj({"code":{"type":"string","const":"unrelated_rendering_artifact"},"evidence":text})}})
assessment.update({"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://foundry.adobe.com/schemas/hp-natural-placement-v4.3-compact-assessment.json","title":"HP Natural Placement V4.3 compact assessment","$defs":{"region":region,"fact":fact,"trigger":trigger,"missing_support_test":missing,"candidate":candidate}})
audit=obj({"protocol_version":text,"model_requested":text,"model_returned":{"type":["string","null"]},"input_fingerprint":{"type":"string","pattern":"^[0-9a-f]{64}$"},"system_prompt_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"assessment_schema_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"wire_schema_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"scoring_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"crop_algorithm_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"anchor_catalog_sha256":{"type":"string","pattern":"^[0-9a-f]{64}$"},"target_record_id":{"type":["string","null"]},"selected_anchor_ids":{"type":"array","maxItems":4,"uniqueItems":True,"items":text},"crop_provenance_sha256":{"type":["string","null"],"pattern":"^[0-9a-f]{64}$"},"derived_sha256":{"type":["string","null"],"pattern":"^[0-9a-f]{64}$"}})
attempt=obj({"attempt":{"type":"integer","minimum":1,"maximum":2},"audit_id":text,"validation_status":{"type":"string","enum":["valid","invalid","transport_error"]},"finish_reason":{"type":["string","null"]},"total_tokens":{"type":["integer","null"],"minimum":0},"refusal":{"type":["string","null"]},"content_bytes":{"type":"integer","minimum":0}})
result=obj({"schema_version":{"type":"string","const":"hp-natural-placement-v4.3-result-v1"},"status":{"type":"string","enum":["ok","error","unassessable"]},"assessment":{"type":["object","null"]},"derived":{"type":["object","null"]},"error":{"anyOf":[{"type":"null"},obj({"code":{"type":"string","enum":["invalid_input","transport_failure","invalid_model_output","unassessable_input","audit_failure"]},"message":text})]},"raw_attempts":{"type":"array","minItems":1,"maxItems":2,"items":attempt},"audit":audit})
result.update({"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://foundry.adobe.com/schemas/hp-natural-placement-v4.3-result.json"})
(ROOT/'assessment_schema.json').write_text(json.dumps(assessment,indent=2)+'\n'); (ROOT/'result_schema.json').write_text(json.dumps(result,indent=2)+'\n')
print('built compact schemas')
